    hudVisible: !document.querySelector('#hud').classList.contains('hidden'),
    canvasSize: [document.querySelector('canvas').width, document.querySelector('canvas').height],
    webgl: !!document.querySelector('canvas').getContext('webgl2'),
    sceneChildren: window.__notUsed ?? null
  }));
  console.log(JSON.stringify({ result, errors }, null, 2));
} finally { await browser.close(); }

